using System.Management.Automation;
using System.Runtime.Versioning;

namespace LibTmux.PowerShell;

/// <summary>Runs a hook through its native owner.</summary>
[Cmdlet(VerbsLifecycle.Invoke, "TmuxHook", DefaultParameterSetName = "Server", SupportsShouldProcess = true)]
[OutputType(typeof(void))]
[UnsupportedOSPlatform("windows")]
public sealed class InvokeTmuxHookCommand : TmuxCmdlet
{
    /// <summary>Gets or sets the native server whose hook table is used.</summary>
    [Parameter(Mandatory = true, ValueFromPipeline = true, Position = 0, ParameterSetName = "Server")]
    [ValidateNotNull]
    public Server? Server { get; set; }

    /// <summary>Gets or sets the native session whose hook table is used.</summary>
    [Parameter(Mandatory = true, ValueFromPipeline = true, Position = 0, ParameterSetName = "Session")]
    [ValidateNotNull]
    public Session? Session { get; set; }

    /// <summary>Gets or sets the native window whose hook table is used.</summary>
    [Parameter(Mandatory = true, ValueFromPipeline = true, Position = 0, ParameterSetName = "Window")]
    [ValidateNotNull]
    public Window? Window { get; set; }

    /// <summary>Gets or sets the native pane whose hook table is used.</summary>
    [Parameter(Mandatory = true, ValueFromPipeline = true, Position = 0, ParameterSetName = "Pane")]
    [ValidateNotNull]
    public Pane? Pane { get; set; }

    /// <summary>Gets or sets the hook name; indexed mutation targets one entry.</summary>
    [Parameter(Mandatory = true)]
    [ValidateNotNullOrEmpty]
    [ValidatePattern(@"\A[^\x00]*[^\s\x00][^\x00]*\z")]
    public string Name { get; set; } = string.Empty;

    /// <summary>Gets or sets an explicit table scope; omission uses the owner scope.</summary>
    [Parameter]
    [ValidateSet("Server", "Session", "Window", "Pane")]
    public OptionScope? Scope { get; set; }

    /// <summary>Gets or sets whether to use the global table.</summary>
    [Parameter]
    public SwitchParameter Global { get; set; }

    private object Owner => (object?)Pane ?? (object?)Window ?? (object?)Session ?? Server!;

    /// <inheritdoc />
    protected override void ProcessRecord()
    {
        object owner = Owner;
        string table = $"{(Global ? "global " : string.Empty)}{Scope?.ToString() ?? owner.GetType().Name}";
        if (ShouldProcess(TmuxOwner.Describe(owner), $"Run {table} tmux hook '{Name}'"))
        {
            var request = new HookRequest(Name) { Scope = Scope, Global = Global };
            ExecuteOperation(token => TmuxOwner.Hooks(owner).RunAsync(request, token), "Tmux.HookInvokeFailed", owner);
        }
    }
}

src/LibTmux.PowerShell/InvokeTmuxPaneCom.content:
using System.Management.Automation;
using System.Runtime.Versioning;

namespace LibTmux.PowerShell;

/// <summary>Runs a shell command in one pane and reports its exit status.</summary>
[Cmdlet(VerbsLifecycle.Invoke, "TmuxPaneCommand", SupportsShouldProcess = true)]
[OutputType(typeof(PaneRunResult))]
[UnsupportedOSPlatform("windows")]
public sealed class InvokeTmuxPaneCommandCommand : TmuxCmdlet
{
    private PaneRunRequest request = null!;

    /// <summary>Gets or sets the native pane that receives the command.</summary>
    [Parameter(Mandatory = true, ValueFromPipeline = true, Position = 0)]
    [ValidateNotNull]
    public Pane Pane { get; set; } = null!;

    /// <summary>Gets or sets the shell command to run in a subshell.</summary>
    [Parameter(Mandatory = true, Position = 1)]
    [ValidateNotNull]
    [AllowEmptyString]
    public string Command { get; set; } = string.Empty;

    /// <summary>Gets or sets the completion wait in seconds, at most one day.</summary>
    [Parameter]
    public double Timeout { get; set; } = 30;

    /// <summary>Gets or sets whether input gets a leading history-suppression space.</summary>
    [Parameter]
    public bool SuppressHistory { get; set; } = true;

    /// <inheritdoc />
    protected override void BeginProcessing()
    {
        if (!double.IsFinite(Timeout) || Timeout < 1d / TimeSpan.TicksPerSecond || Timeout > 86400)
        {
            ThrowTerminatingError(new ErrorRecord(
                new ArgumentOutOfRangeException(nameof(Timeout),
                    "Timeout must be a finite number of seconds between 0.0000001 and 86400."),
                "Tmux.InvalidTimeout", ErrorCategory.InvalidArgument, Timeout));
        }

        try
        {
            request = new PaneRunRequest(Command)
            {
                Timeout = TimeSpan.FromSeconds(Timeout),
                KeepOutOfHistory = SuppressHistory,
            };
            request.Validate();
        }
        catch (ArgumentException error)
        {
            ThrowTerminatingError(new ErrorRecord(error,
                "Tmux.InvalidPaneCommand", ErrorCategory.InvalidArgument, Command));
        }
    }

    /// <inheritdoc />
    protected override void ProcessRecord()
    {
        string endpoint = Pane.Server.ConnectionOptions.SocketPath
            ?? Pane.Server.ConnectionOptions.SocketName
            ?? "default tmux endpoint";
        if (ShouldProcess($"{endpoint} pane {Pane.Id}", "Run shell command"))
        {
            ReadResult(
                async token =>
                {
                    await TmuxFeatures.RequireNamedBuffersAsync(Pane.Server, "Invoke-TmuxPaneCommand", token).ConfigureAwait(false);
                    return await Pane.RunAsync(request, token).ConfigureAwait(false);
                },
                "Tmux.PaneCommandFailed",
                Pane);
        }
    }
}

src/LibTmux.PowerShell/InvokeTmuxQueryCo.content:
using System.Management.Automation;
using System.Runtime.Versioning;
using LibTmux.Query;

namespace LibTmux.PowerShell;

/// <summary>Executes a native query or explicit raw filter against a supplied server.</summary>
[Cmdlet(VerbsLifecycle.Invoke, "TmuxQuery", DefaultParameterSetName = "Query")]
[OutputType(typeof(Session), typeof(Window), typeof(Pane),
    typeof(QueryResult<Session>), typeof(QueryResult<Window>), typeof(QueryResult<Pane>))]
[UnsupportedOSPlatform("windows")]
public sealed class InvokeTmuxQueryCommand : TmuxCmdlet
{
    private object? acceptedPlan;
    private UnsafeTmuxFilter? acceptedFilter;

    /// <summary>Gets or sets the explicit endpoint to inspect and query.</summary>
    [Parameter(Mandatory = true, ValueFromPipeline = true, Position = 0)]
    [ValidateNotNull]
    public Server Server { get; set; } = null!;

    /// <summary>Gets or sets the document planned using the inspected daemon version.</summary>
    [Parameter(Mandatory = true, ParameterSetName = "Query")]
    [ValidateNotNull]
    public QueryDocument? Query { get; set; }

    /// <summary>Gets or sets a native Session, Window, or Pane plan prepared for this daemon version.</summary>
    [Parameter(Mandatory = true, ParameterSetName = "Plan")]
    [ValidateNotNull]
    public object? Plan { get; set; }

    /// <summary>Gets or sets source evaluation policy when executing a document.</summary>
    [Parameter(ParameterSetName = "Query")]
    [ValidateSet(nameof(QueryPushdown.Auto), nameof(QueryPushdown.Never), nameof(QueryPushdown.Require))]
    public QueryPushdown Pushdown { get; set; } = QueryPushdown.Auto;

    /// <summary>Gets or sets whether to emit one native result retaining its complete snapshot.</summary>
    [Parameter(ParameterSetName = "Query")]
    [Parameter(ParameterSetName = "Plan")]
    public SwitchParameter AsResult { get; set; }

    /// <summary>Gets or sets the entity searched by the raw native filter.</summary>
    [Parameter(Mandatory = true, ParameterSetName = "NativeFilter")]
    [ValidateSet("Session", "Window", "Pane")]
    public QueryTarget Target { get; set; }

    /// <summary>Gets or sets uninterpreted tmux filter text; raw rows do not form a complete query snapshot.</summary>
    [Parameter(Mandatory = true, ParameterSetName = "NativeFilter")]
    [ValidateNotNullOrEmpty]
    public string? NativeFilter { get; set; }

    /// <inheritdoc />
    protected override void BeginProcessing()
    {
        try
        {
            switch (ParameterSetName)
            {
                case "Plan":
                    acceptedPlan = QuerySource.ValidatePlan(Plan is PSObject wrapper ? wrapper.BaseObject : Plan!);
                    break;
                case "NativeFilter":
                    QuerySource.ValidateTarget(Target);
                    if (NativeFilter!.Contains('\0'))
                    {
                        throw new ArgumentException("A native tmux filter cannot contain a NUL character.", nameof(NativeFilter));
                    }
                    acceptedFilter = new UnsafeTmuxFilter(NativeFilter);
                    break;
                default:
                    QuerySource.ValidateTarget(Query!.Target);
                    break;
            }
        }
        catch (Exception exception) when (exception is ArgumentException or UnsupportedQueryExpressionException)
        {
            ThrowTerminatingError(new ErrorRecord(exception, "Tmux.InvalidQuerySource", ErrorCategory.InvalidArgument,
                ParameterSetName == "Plan" ? Plan : ParameterSetName == "NativeFilter" ? NativeFilter : Query));
        }
    }

    /// <inheritdoc />
    protected override void ProcessRecord() =>
        ReadResult(ExecuteAsync, "Tmux.QueryExecutionFailed", Server, enumerateCollection: !AsResult);

    private Task<object> ExecuteAsync(CancellationToken cancellationToken) => ParameterSetName switch
    {
        "Plan" => QuerySource.ExecutePlanAsync(Server, acceptedPlan!, cancellationToken),
        "NativeFilter" => QuerySource.ExecuteNativeAsync(Server, Target, acceptedFilter!, cancellationToken),
        _ => QuerySource.ExecuteDocumentAsync(Server, Query!, Pushdown, cancellationToken),
    };
}

